# Let me represent each shape as a 2D pattern
def get_shape_pattern(grid, color):
    """Get the shape pattern as a 2D grid of 0s and color or 0 (for empty)"""
    rows = [r for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == color]
    if not rows:
        return None

    shape_cells = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == color]
    if not shape_cells:
        return None

    min_r, max_r = min(r for r, c in shape_cells), max(r for r, c in shape_cells)
    min_c, max_c = min(c for r, c in shape_cells), max(c for r, c in shape_cells)

    h = max_r - min_r + 1
    w = max_c - min_c + 1

    pattern = []
    for dr in range(h):
        row = []
        for dc in range(w):
            r, c = min_r + dr, min_c + dc
            if grid[r][c] == color:
                row.append(color)
            else:
                row.append(0)  # background in the shape
        pattern.append(row)
    return pattern, (min_r, min_c), (max_r, max_c)

