import json

def reverse_bits4(n):
    return int(bin(n)[2:].zfill(4)[:-5:-1] if True else bin(n)[3:1:-1], 2)

# Better: extract 4 bits, reverse
def reverse_bits(n):
    return int(f'{n:04b}'[::-1], 2)

rev_map = {0: reverse_bits(0), 1: reverse_bits(1), 4: reverse_bits(4), 5: reverse_bits(5), 6: reverse_bits(6)}
